from abc import ABC, abstractmethod

# Abstracción: interfaz para estrategias de descuento
class DiscountStrategy(ABC):
    @abstractmethod
    def apply(self, price: float) -> float:
        pass

    @property
    @abstractmethod
    def name(self) -> str:
        pass

# Implementaciones concretas (una por tipo de descuento)
class PercentageDiscount(DiscountStrategy):
    def __init__(self, percentage: float):
        self.percentage = percentage

    def apply(self, price: float) -> float:
        return price * (1 - self.percentage / 100)

    @property
    def name(self) -> str:
        return f'Percentage ({self.percentage}%)'

class FixedDiscount(DiscountStrategy):
    def __init__(self, amount: float):
        self.amount = amount

    def apply(self, price: float) -> float:
        return max(0, price - self.amount)  # No puede ser negativo

    @property
    def name(self) -> str:
        return f'Fixed (${self.amount})'

class BuyOneGetOneDiscount(DiscountStrategy):
    def apply(self, price: float) -> float:
        return price / 2

    @property
    def name(self) -> str:
        return 'Buy One Get One'

# Para agregar nuevo descuento: SOLO CREAR NUEVA CLASE
# NO MODIFICAS ninguna clase existente
class SeasonalDiscount(DiscountStrategy):
    def __init__(self, season: str, percentage: float):
        self.season = season
        self.percentage = percentage

    def apply(self, price: float) -> float:
        return price * (1 - self.percentage / 100)

    @property
    def name(self) -> str:
        return f'Seasonal ({self.season}, {self.percentage}%)'

# Calculator genérico: funciona con CUALQUIER DiscountStrategy
# NO NECESITA MODIFICARSE para nuevos tipos de descuento
class DiscountCalculator:
    def calculate(self, price: float, strategy: DiscountStrategy) -> float:
        return strategy.apply(price)

# Uso:
calculator = DiscountCalculator()

# Descuentos existentes (funcionan igual que antes)
print(calculator.calculate(100, PercentageDiscount(20)))  # 80.0
print(calculator.calculate(100, FixedDiscount(30)))       # 70.0
print(calculator.calculate(100, BuyOneGetOneDiscount()))  # 50.0

# Nuevo descuento: SOLO CREAR INSTANCIA, NO MODIFICAR CÓDIGO
print(calculator.calculate(100, SeasonalDiscount('Summer', 25)))  # 75.0

