class DiscountRegistry:
    '''Registro dinámico de descuentos (plugin architecture)'''

    def __init__(self):
        self._strategies = {}

    def register(self, name, strategy_class):
        if not issubclass(strategy_class, DiscountStrategy):
            raise TypeError(f'{strategy_class} must inherit from DiscountStrategy')
        self._strategies[name] = strategy_class

    def create(self, name, *args, **kwargs):
        if name not in self._strategies:
            raise ValueError(f'Unknown discount: {name}')
        return self._strategies[name](*args, **kwargs)

    def list_available(self):
        return list(self._strategies.keys())

# Registro
registry = DiscountRegistry()
registry.register('percentage', PercentageDiscount)
registry.register('fixed', FixedDiscount)
registry.register('seasonal', SeasonalDiscount)
registry.register('student', StudentDiscount)

print('--- Plugin Registry ---')
print(f'Descuentos disponibles: {registry.list_available()}')
print()

# Crear instancias dinámicamente
for name in registry.list_available():
    if name == 'percentage':
        strategy = registry.create(name, 20)
    elif name == 'fixed':
        strategy = registry.create(name, 30)
    elif name == 'seasonal':
        strategy = registry.create(name, 'Winter', 15)
    elif name == 'student':
        strategy = registry.create(name, 'S99999')

    print(f'  {strategy.name}: ${calc.calculate(100, strategy)}')

print()
print('✓ Nuevo descuento: solo registry.register(), sin modificar código')
